public sealed class PersonGateway {
    public long Id { get; set; }
    public string LastName { get; set; } = "";
    public int Deps { get; set; }

    public static PersonGateway? Find(DbConnection db, long id) =>
        db.QuerySingleOrDefault<PersonGateway>(
            "SELECT id, last_name, deps FROM people WHERE id = @id", new { id });

    public int Update(DbConnection db) => db.Execute(
        "UPDATE people SET last_name = @LastName, deps = @Deps WHERE id = @Id", this);
}
